// Verify X-LV-Signature = sha256 HMAC of the RAW body with INTERNAL_HMAC_SECRET (constant-time), then parse.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false (same as W22).
const crypto = require('crypto');
const first = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const sig = String((first.json.headers || {})['x-lv-signature'] || '').replace(/^sha256=/, '');
const want = crypto.createHmac('sha256', $env.INTERNAL_HMAC_SECRET || '').update(raw).digest('hex');
let valid = false, ev = null, reason = '';
try { valid = sig.length === want.length && crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(want, 'hex')); } catch (e) { valid = false; }
if (!valid) reason = 'bad_signature';
try { ev = JSON.parse(raw.toString('utf8')); } catch (e) { valid = false; reason = 'bad_json'; }
if (valid && 900000 > 0) { const age = Math.abs(Date.now() - Date.parse(ev.occurred_at || '')); if (!(age < 900000)) { valid = false; reason = 'stale_or_replayed'; } }
return [{ json: { valid, reason, event: valid ? ev : null } }];

// Pure function of the broker row + event. Mirrors portal/spec/README.md (7 steps, 5 blocking).
const b = $('Load broker').first().json;
const ev = $('Verify signature').first().json.event;
const P = b.onboarding_progress || {};
const STEPS = [
  { key: 'profile', title: 'Your details and FSP number', minutes: '3 minutes', blocking: true },
  { key: 'calendar', title: 'Connect your Outlook calendar', minutes: '1 minute', blocking: true },
  { key: 'availability', title: 'Check your hours', minutes: '1 minute', blocking: true },
  { key: 'agreement', title: 'Sign your agreement', minutes: '3 minutes', blocking: true },
  { key: 'card', title: 'Approve your intro card', minutes: '1 minute', blocking: true },
  { key: 'media', title: 'Record your 25-second intro', minutes: '10 minutes', blocking: false },
];
const isDone = (k) => ['done', 'skipped', 'defaulted'].includes((P[k] || {}).status);
const next = STEPS.find((s) => !isDone(s.key)) || null;
const doneStep = STEPS.find((s) => s.key === ev.step) || null;
const first = String(b.adviser_name || 'there').trim().split(/\s+/)[0];
return [{ json: { broker: b, event: ev, first_name: first, next_step: next, done_step: doneStep, in_portal: !!b.in_portal } }];

const s = $('Derive state').first().json;
const link = $json;
const token = link.hashed_token || (link.properties && link.properties.hashed_token) || '';
const first = s.first_name;
const portal = String($env.PORTAL_URL || '').replace(/\/$/, '');
const out = [];
out.push({ json: { channel: 'wa', broker_id: s.broker.broker_id, to: s.broker.adviser_whatsapp, template: 'broker_onboarding_welcome',
  params: [first], buttons: [{ index: 0, suffix: token }, { index: 1, suffix: 'start' }], log_type: 'welcome', idem: 'welcome:' + s.broker.broker_id } });
out.push({ json: { channel: 'email', broker_id: s.broker.broker_id, to: s.broker.email, log_type: 'welcome', idem: 'welcome-email:' + s.broker.broker_id,
  subject: 'Welcome to SortMyCover: 3 minutes to see what to do next',
  paragraphs: [
    'Hi ' + first + ', your account is ready.',
    '1. Open your portal with the link below (no password needed).',
    '2. Watch the 3-minute video. It has captions, so you can watch it on mute.',
    '3. Follow the seven steps. Most people finish in about 12 minutes.',
    'If you get stuck, reply to this email or message us on WhatsApp. You do not need a call.'],
  cta: { text: 'Open my portal', url: portal + '/m/' + token }, cta2: { text: 'Watch the 3-minute video', url: portal + '/v/start' } } });
return out;

// Verdicts: verified | blocked | pending_manual. Rules in portal/spec/02-profile.md.
const s = $('Derive state').first().json;
const b = s.broker;
const res = $json || {};
const body = res.body && typeof res.body === 'object' ? res.body : {};
const attempts = 1;
const norm = (t) => String(t || '').toLowerCase().replace(/\(pty\)|\bltd\b|\bcc\b|\binc\b|\bt\/a\b/g, ' ').replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter((w) => w && w !== 'and' && w !== 'the');
const jac = (a, b2) => { const A = new Set(a), B = new Set(b2); if (!A.size || !B.size) return 0; let i = 0; A.forEach((x) => { if (B.has(x)) i++; }); return i / (A.size + B.size - i); };
const httpOk = Number(res.statusCode || 0) >= 200 && Number(res.statusCode || 0) < 300 && typeof body === 'object' && 'found' in body;
let verdict, reason, score = 0;
const ACTIVE = /^(authori[sz]ed|active)$/i;
const LIFE = new RegExp($env.FSCA_LIFE_CATEGORY_PATTERN || 'long.?term|life', 'i');   // ASSUMPTION: confirm against the register (needs_human NH-BS-09)
if (!httpOk) { verdict = 'pending_manual'; reason = 'lookup_error'; }
else if (!body.found) { verdict = 'blocked'; reason = 'not_found'; }
else if (!ACTIVE.test(String(body.status || ''))) { verdict = 'blocked'; reason = 'not_active:' + String(body.status || '').slice(0, 40); }
else {
  const reg = norm(body.register_name);
  score = Math.max(jac(reg, norm(b.practice_name)), jac(reg, norm(b.practice_legal_name || '')));
  const cats = (body.categories || []).join(' ');
  if (score < 0.6) { verdict = 'blocked'; reason = 'name_mismatch'; }
  else if (!LIFE.test(cats)) { verdict = 'blocked'; reason = 'not_authorised_for_life'; }
  else { verdict = 'verified'; reason = 'ok'; }
}
const fsp_check = { status: verdict, reason, checked_at: new Date().toISOString(), register_name: body.register_name || null, register_status: body.status || null, categories: body.categories || [], name_score: Math.round(score * 100) / 100, attempts, source: 'FSCA_REGISTER_URL', by: 'system' };
return [{ json: { broker_id: b.broker_id, verdict, reason, fsp_check, fsp_number: b.fsp_number, practice_name: b.practice_name, register_name: body.register_name || null, first_name: s.first_name, to_wa: b.adviser_whatsapp, to_email: b.email } }];

// Soft wording to the broker, factual alert to Jonathan/KG (via W22: 'FSCA check mismatch', 6.3 alerts).
const r = $('Evaluate FSCA result').first().json;
const pending = r.verdict === 'pending_manual';
const what = pending ? 'We could not reach the FSCA register just now.' : 'We could not match your FSP number to your practice name.';
const fix = pending ? 'We are checking it by hand and will message you today. Nothing for you to do.' : 'Check the number and try again. After three tries we will check it by hand.';
return [
 { json: { channel: 'wa', broker_id: r.broker_id, to: r.to_wa, template: 'broker_onboarding_issue', params: [r.first_name, what, fix], buttons: [{ index: 0, suffix: 'profile' }], log_type: 'fsp_issue', idem: 'fsp-issue:' + r.broker_id + ':' + r.fsp_check.checked_at } },
 { json: { channel: 'w22', kind: 'signal', signal_key: 'fsca_check_' + (pending ? 'pending_manual' : 'mismatch'), scope: 'broker:' + r.broker_id, severity: pending ? 'amber' : 'red', source: 'W20',
   what: 'FSCA check ' + (pending ? 'could not complete' : 'failed') + ' for FSP ' + r.fsp_number + ' (' + r.reason + ')',
   impact: 'Broker cannot go live; no leads are routed until verified', first_action: 'Open the broker in the console, check the FSCA register, tap Verified or ask the broker to correct the number',
   register_name: r.register_name, since: new Date().toISOString() } }
];

const s = $('Derive state').first().json;
const slots = Array.isArray($json.slots) ? $json.slots : [];
const first = slots[0] || null;
let label = null;
if (first) { label = DateTime.fromISO(first.start, { zone: 'Africa/Johannesburg' }).toFormat("ccc d LLL, HH:mm"); }
return [{ json: { broker_id: s.broker.broker_id, first_name: s.first_name, to_wa: s.broker.adviser_whatsapp, in_portal: s.in_portal, slot_count: slots.length, next_free_slot_at: first ? first.start : null, next_free_slot_label: label } }];

