  if (r.in_portal) return [];
  return [{ json: { channel: 'wa', broker_id: r.broker_id, to: r.to_wa, template: 'broker_calendar_ok', params: [r.first_name, r.next_free_slot_label], buttons: [{ index: 0, suffix: 'availability' }], log_type: 'calendar_ok', idem: 'cal-ok:' + r.broker_id + ':' + r.next_free_slot_at } }];
}
return [{ json: { channel: 'wa', broker_id: r.broker_id, to: r.to_wa, template: 'broker_onboarding_issue', params: [r.first_name, 'Your calendar is connected, but we cannot see any free time in the next 14 days.', 'Check your hours in the portal, or your Outlook working hours.'], buttons: [{ index: 0, suffix: 'calendar' }], log_type: 'calendar_no_slots', idem: 'cal-noslots:' + r.broker_id + ':' + new Date().toISOString().slice(0, 13) } }];

