parameters.query:
update public.brokers set status = 'active', routing_on = true, approved_live_by = $2::uuid, approved_live_at = now()
where broker_id = $1::uuid and status = 'ready_for_go_live'
returning broker_id, adviser_name, adviser_whatsapp, email, practice_name;

parameters.jsCode:
const b = $('Activate broker').first().json;
const first = String(b.adviser_name || 'there').trim().split(/\s+/)[0];
const now = DateTime.now().setZone('Africa/Johannesburg');
let mon = now.plus({ days: 1 }); while (mon.weekday !== 1) mon = mon.plus({ days: 1 });
const day = mon.toFormat('cccc d LLL');
const portal = String($env.PORTAL_URL || '').replace(/\/$/, '');
return [
 { json: { channel: 'wa', broker_id: b.broker_id, to: b.adviser_whatsapp, template: 'broker_live', params: [first, day], buttons: [], log_type: 'live', idem: 'live:' + b.broker_id } },
 { json: { channel: 'email', broker_id: b.broker_id, to: b.email, log_type: 'live', idem: 'live-email:' + b.broker_id,
   subject: "You're live on SortMyCover: what to expect in week 1",
   paragraphs: ['Hi ' + first + ', you are live. What to expect:',
     '1. Bookings appear in your Outlook calendar on their own.',
     '2. After each meeting we ask for three quick taps: what happened, how the lead was, a score. It takes about 20 seconds.',
     '3. Replacements: a no-show, a number we cannot reach, or a lead outside the age or budget we agreed can be replaced, up to your limit.',
     '4. Your weekly report arrives on Monday at 07:00.',
     'Questions? Reply to this email.'],
   cta: { text: 'Open my leads', url: portal + '/broker/leads' } } } ];

// Quiet hours: nothing is sent 19:00-08:00 SAST; due nudges go at 08:00. Defaults and SLA stamps still run (other branches).
const h = DateTime.now().setZone('Africa/Johannesburg').hour;
return h >= 8 && h < 19 ? [{ json: { go: true } }] : [];

// Copy bank: portal/spec/10-nudges-and-go-live.md. One nudge, one stalled step, no third nudge ever.
const REASON24 = { profile: "It also shows leads you're on the FSCA register.", calendar: 'One tap. It lets leads book real free times with you.', availability: "We've used standard hours (Mon-Fri 9 to 5, 3 a day). Change them any time.", agreement: "It's in plain words, and you get a copy straight away.", card: "It's the picture leads see before they meet you.", media: 'People show up for people. Leads who see your face first are far less likely to no-show.' };
const REASON72 = { profile: 'We check every FSP number before any lead is sent to you.', calendar: 'If Microsoft asks for admin approval, the portal has a link for your IT person, or a shared-calendar option.', availability: "We've used standard hours, so this can wait.", agreement: "You can read it first. It's month to month, with no contract.", card: 'Leads see this on WhatsApp the moment they book.', media: 'No rush. You can go live without it and add it later.' };
const STEPS = [['profile','Your details and FSP number','3 minutes'],['calendar','Connect your Outlook calendar','1 minute'],['availability','Check your hours','1 minute'],['agreement','Sign your agreement','3 minutes'],['card','Approve your intro card','1 minute'],['media','Record your 25-second intro','10 minutes']];
const portal = String($env.PORTAL_URL || '').replace(/\/$/, '');
const out = [];
for (const it of $input.all()) {
  const b = it.json; const P = b.onboarding_progress || {};
  const done = (k) => ['done','skipped','defaulted'].includes((P[k] || {}).status);
  const step = STEPS.find((s) => !done(s[0])); if (!step) continue;
  const first = String(b.adviser_name || 'there').trim().split(/\s+/)[0];
  const [key, title, minutes] = step;
  const blocking = key !== 'media';
  const use72 = b.due === '72h' && blocking;     // media never gets the "leads can't be sent" wording
  out.push({ json: { channel: 'wa', broker_id: b.broker_id, to: b.adviser_whatsapp, template: use72 ? 'broker_onboarding_nudge_72h' : 'broker_onboarding_nudge_24h',
    params: use72 ? [first, title, REASON72[key]] : [first, title, minutes, REASON24[key]], buttons: [{ index: 0, suffix: key }], log_type: 'nudge_' + b.due, idem: 'nudge:' + b.due + ':' + b.broker_id + ':' + b.onboarding_last_progress_at,
    mark: { due: b.due, since: b.onboarding_last_progress_at } } });
  if (b.due === '72h') {
    out.push({ json: { channel: 'email', broker_id: b.broker_id, to: b.email, log_type: 'nudge_72h_email', idem: 'nudge-email:' + b.broker_id + ':' + b.onboarding_last_progress_at,
      subject: 'Your SortMyCover setup: one step left (' + title + ')',
      paragraphs: ['Hi ' + first + ", you're nearly there. The one thing left is: " + title + '. It takes about ' + minutes + '.', REASON72[key], 'Prefer to ask something first? Reply to this email or WhatsApp us. We answer the same day. No call needed.'],
      cta: { text: 'Finish setup', url: portal + '/s/' + key } } });
    out.push({ json: { channel: 'w22', kind: 'signal', signal_key: 'broker_onboarding_stalled', scope: 'broker:' + b.broker_id, severity: 'amber', source: 'W20', what: b.practice_name + ' has not progressed for 72 h (stalled at: ' + title + ')', impact: 'Not live yet; delays first leads', first_action: 'Send a short WhatsApp offering help (a call only if the broker prefers)', since: new Date().toISOString() } });
  }
}
return out;

