-- Marked BEFORE sending: a duplicate nudge is worse than a missed one (the 72-h and Jonathan's to-do cover a miss).
update public.brokers set onboarding_nudges = coalesce(onboarding_nudges,'{}'::jsonb) || jsonb_build_object('since', $2::timestamptz, $3, now()) || case when $3 = '72h' then jsonb_build_object('24h', coalesce(onboarding_nudges->>'24h', to_char(now(),'YYYY-MM-DD"T"HH24:MI:SSOF'))) else '{}'::jsonb end
where broker_id = $1::uuid returning broker_id;

