// Re-enters lane A through the signed webhook so there is one code path for 'step done'.
const crypto = require('crypto');
const out = [];
for (const it of $input.all()) {
  const body = JSON.stringify({ event_id: 'avail-default:' + it.json.broker_id + ':' + new Date().toISOString().slice(0, 10), type: 'step.completed', broker_id: it.json.broker_id, step: 'availability', occurred_at: new Date().toISOString(), payload: { by: 'system', defaulted: true } });
  const sig = crypto.createHmac('sha256', $env.INTERNAL_HMAC_SECRET || '').update(body).digest('hex');
  await this.helpers.httpRequest({ method: 'POST', url: $env.N8N_PUBLIC_URL + '/webhook/w20/broker-event', headers: { 'content-type': 'application/json', 'x-lv-signature': 'sha256=' + sig }, body });
  out.push({ json: { broker_id: it.json.broker_id, emitted: true } });
}
return out;

// Template send. Staging safety: with DRY_RUN_SENDS=true only WHATSAPP_TEST_RECIPIENTS get a real send; others are logged as skipped.
const allow = String($env.WHATSAPP_TEST_RECIPIENTS || '').split(',').map((x) => x.trim().replace(/^\+/, '')).filter(Boolean);
return $input.all().map((it) => {
  const j = it.json; const to = String(j.to || '').replace(/[^0-9]/g, '');
  const clean = (t) => String(t == null ? '' : t).replace(/[\n\t]+/g, ' ').replace(/ {5,}/g, '    ').trim();
  const components = [];
  if ((j.params || []).length) components.push({ type: 'body', parameters: j.params.map((t) => ({ type: 'text', text: clean(t) })) });
  for (const bt of (j.buttons || [])) if (bt.suffix) components.push({ type: 'button', sub_type: 'url', index: String(bt.index), parameters: [{ type: 'text', text: String(bt.suffix) }] });
  const dry = String($env.DRY_RUN_SENDS || 'false') === 'true' && !allow.includes(to);
  return { json: { ...j, send: !dry && !!to, skip_reason: dry ? 'dry_run_not_allow_listed' : (!to ? 'no_number' : null),
    payload: { messaging_product: 'whatsapp', to, type: 'template', template: { name: j.template, language: { code: 'en' }, components } } } };
});

// From HOWZIT_MAILBOX, bcc HOWZIT_MAILBOX (one audit trail, 4.10 item 0). Plain, near-text email on purpose (founder-style, no brand colours needed).
const mailbox = $env.HOWZIT_MAILBOX || 'howzit@leadvelocity.co.za';
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $input.all().map((it) => {
  const j = it.json;
